d=$(mktemp -d) && cd "$d" && brv vc init >/dev/null 2>&1 && mkdir -p .brv/context-tree/auth && printf '%s\n' '# Auth' '' 'Auth uses a fixed-window rate limiter and issues a JWT-like token with a 24 hour (86400s) expiry.' > .brv/context-tree/auth/notes.md && brv vc add . >/dev/null 2>&1 && brv vc config user.name "receipt-check" >/dev/null 2>&1 && brv vc config user.email "receipt-check@example.invalid" >/dev/null 2>&1 && brv vc commit -m "Add auth notes" >/dev/null 2>&1 && p=$(brv search "rate limiter" --format json) && echo "$p" | grep -q '"totalFound":1' && echo "POSITIVE ASSERTION PASS: BM25 search found the just-committed auth/notes.md" && n=$(brv search "zzznonexistentxyz123" --format json) && echo "$n" | grep -q '"totalFound":0' && echo "NEGATIVE CONTROL PASS: 0 results for a term that does not exist"; ec=$?; rm -rf "$d"; exit $ec
